import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        D = int(next(iterator))

        snakes = []
        for _ in range(N):
            T = int(next(iterator))
            L = int(next(iterator))
            snakes.append((T, L))

        for k in range(1, D + 1):
            max_w = 0
            for t, l in snakes:
                w = t * (l + k)
                if w > max_w:
                    max_w = w
            print(max_w)

    except StopIteration:
        pass

if __name__ == '__main__':
    solve()

